package org.humanjourney.core.juice;
import net.minecraft.commands.*;
import net.minecraft.network.chat.Component;
import net.minecraftforge.event.RegisterCommandsEvent;
import com.mojang.brigadier.arguments.*;
import java.util.*;
public final class JuiceCommands {
 public static void register(RegisterCommandsEvent e){e.getDispatcher().register(Commands.literal("hjcore").then(Commands.literal("juice").requires(s->s.hasPermission(2)).executes(c->{var source=c.getSource();try{var item=source.getPlayerOrException().getMainHandItem();var state=JuiceStore.state();source.sendSuccess(()->Component.literal("Juices="+state.catalog().definitions().size()+" | source="+state.source()+" | revision="+state.revision()+(state.error()==null?"":" | reload error="+state.error())+"\nHeld: "+(JuiceState.marked(item)?JuiceContainers.describe(item):"not a juice canteen")),false);return 1;}catch(Exception ex){source.sendFailure(Component.literal(ex.getMessage()));return 0;}}).then(Commands.literal("list").executes(c->list(c.getSource(),1)).then(Commands.argument("page",IntegerArgumentType.integer(1)).executes(c->list(c.getSource(),IntegerArgumentType.getInteger(c,"page"))))).then(Commands.literal("show").then(Commands.argument("id",StringArgumentType.word()).suggests((c,b)->SharedSuggestionProvider.suggest(JuiceStore.state().catalog().definitions().keySet(),b)).executes(c->{var source=c.getSource();var id=StringArgumentType.getString(c,"id");var d=JuiceStore.state().catalog().definitions().get(id);if(d==null){source.sendFailure(Component.literal("Unknown juice ID: "+id));return 0;}source.sendSuccess(()->Component.literal("Juice "+d.id()+" | bottle="+d.bottleItem()+" | ingredient="+d.ingredient().describe()+" | name="+d.canteenDisplayName()+" | heal_per_drink="+d.healPerDrink()),false);return 1;})))));}
 private static int list(CommandSourceStack source,int page){var ids=new ArrayList<>(new TreeSet<>(JuiceStore.state().catalog().definitions().keySet()));int pages=Math.max(1,(ids.size()+11)/12);if(page>pages){source.sendFailure(Component.literal("Juice page out of range 1.."+pages));return 0;}source.sendSuccess(()->Component.literal("Juices "+ids.size()+" | page "+page+"/"+pages+": "+ids.subList((page-1)*12,Math.min(page*12,ids.size()))),false);return 1;}
 private JuiceCommands(){}
}
